import re
import sys
from pathlib import Path

LINE_RE = re.compile(
    r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) ERROR \[([^\]]+)\] (.*)$"
)


def parse_errors(path):
    rows = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = LINE_RE.match(line.rstrip("\r\n"))
            if m:
                rows.append({"time": m[1], "module": m[2], "message": m[3]})
    return rows


def render_table(rows):
    esc = lambda s: s.replace("|", "\\|")
    lines = ["| time | module | message |", "|---|---|---|"]
    for r in rows:
        lines.append(
            f"| {esc(r['time'])} | {esc(r['module'])} | {esc(r['message'])} |"
        )
    return "\n".join(lines)


if __name__ == "__main__":
    path = sys.argv[1] if len(sys.argv) > 1 else Path(__file__).with_name("sample.log")
    sys.stdout.reconfigure(encoding="utf-8")
    print(render_table(parse_errors(path)))
EOF
